// Intrinsic sizes for every local image, keyed by site path. Generated by
// `npm run images` from scripts/optimize-images.js and committed so the build
// does not need sharp. Used by:
//   * the image-dimensions transform in .eleventy.js (D6: width/height on <img>);
//   * gallery-tile.liquid (data-bytes, so gallery.liquid can skip preloading a
//     heavy lightbox neighbour).
const fs = require("fs");
const path = require("path");

let files = {};
try {
	const cache = JSON.parse(
		fs.readFileSync(path.join(__dirname, "cache", "images-cache.json"), "utf8"),
	);
	files = cache.files || {};
} catch {
	// No manifest yet: pages build exactly as they did before Item 8.
	files = {};
}

module.exports = files;
